constexpr int MOD = 998244353;

struct modular {
	int val;

	explicit constexpr operator int() const { return val; }

	constexpr modular() : val(0) {}

	constexpr modular(int v) : val(v) {
		assert(0 <= v && v < MOD);
	}

#define COMPAREOP(OP) \
	constexpr bool operator OP(modular b) const { return val OP b.val; }

	COMPAREOP(==)
	COMPAREOP(!=)
	COMPAREOP(<)
	COMPAREOP(>)
	COMPAREOP(<=)
	COMPAREOP(>=)

#undef COMPAREOP

	constexpr modular operator-() const {
		return modular(val ? MOD - val : 0);
	}

	constexpr modular& operator+=(modular m) {
		if ((val += m.val) >= MOD) val -= MOD;
		return *this;
	}

	constexpr modular& operator-=(modular m) {
		if ((val -= m.val) < 0) val += MOD;
		return *this;
	}

	constexpr modular& operator*=(modular m) {
		val = static_cast<int>(
			static_cast<std::int64_t>(val) * m.val % MOD
		);
		return *this;
	}

	template<class T>
	constexpr modular pow(T p) const {
		modular a = *this;
		modular ans = 1;

		for (; p; p /= 2, a *= a) {
			if (p & 1) ans *= a;
		}

		return ans;
	}

	constexpr modular inv() const {
		int a = val;
		int b = MOD;
		int ax = 1;
		int bx = 0;

		while (b) {
			const int q = a / b;
			int t = a % b;
			a = b;
			b = t;

			t = ax - bx * q;
			ax = bx;
			bx = t;
		}

		assert(a == 1);
		if (ax < 0) ax += MOD;
		return modular(ax);
	}

	constexpr modular& operator/=(modular m) {
		return (*this) *= m.inv();
	}

#define ARITHBINARYOP(OP) \
	friend constexpr modular operator OP(modular a, modular b) { \
		return a OP##= b; \
	}

	ARITHBINARYOP(+)
	ARITHBINARYOP(-)
	ARITHBINARYOP(*)
	ARITHBINARYOP(/)

#undef ARITHBINARYOP

	friend std::ostream& operator<<(std::ostream& str, modular x) {
		return str << (x.val > MOD / 2 ? x.val - MOD : x.val);
	}
};

void process(int* const first, int* const last, int n) {
	std::for_each(first, last, [&](int& x) {
		x = static_cast<int>(modular(x).pow(n));
	});
}

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);

	int n;
	std::cin >> n;

	const auto mul_1pow = [](modular a, int b) {
		if (b & 1) a = -a;
		return a;
	};

	const auto mul3 = [](modular a) {
		return a + a + a;
	};

	int i = 0;
	modular three_pow_i = 1;

	std::vector<modular> inv(std::max(3, n + 1));
	inv[1] = 1;

	for (unsigned i = 2; i < inv.size(); ++i) {
		inv[i] = static_cast<int>(
			(static_cast<std::int64_t>(MOD) * MOD
			 - static_cast<std::int64_t>(inv[MOD % i].val) * (MOD / i))
			% MOD
		);
	}

	std::vector<int> tmp_pow_base(n);

	for (; i < n; ++i, three_pow_i = mul3(three_pow_i)) {
		tmp_pow_base[i] = static_cast<int>(1 - three_pow_i);
	}

	int* const first = tmp_pow_base.data();
	int* const last = tmp_pow_base.data() + n;
	process(first, last, n);

	i = 0;
	modular ff = MOD - 1;
	modular out = 0;

	for (; i < n; ++i, ff *= (MOD - (n + 1 - i)) * inv[i]) {
		out.val = static_cast<int>(
			(out.val
			 + static_cast<std::int64_t>(tmp_pow_base[i])
			 * static_cast<int>(ff))
			% MOD
		);
	}

	out = mul3(out);

	const modular three_pow_n_minus_one = modular(3).pow(n - 1);
	const auto zz = -three_pow_n_minus_one;
	const auto three_pow_n = mul3(three_pow_n_minus_one);
	const auto hh = -three_pow_n;

	out += ((zz + 1).pow(n) - zz.pow(n))
		* mul_1pow(three_pow_n + three_pow_n, n + 1);

	out += mul_1pow(
		mul3((hh + 1).pow(n) - hh.pow(n)),
		n
	);

	std::cout << static_cast<int>(out) << '\n';
}

